 "content": "def transform(grid):
    # Each periodic tile has distinct interior fill and divider background.
    # The output encodes the sampled special marker at tile top-left corners;
    # if the intersection is the divider color, use the tile interior color.
    h, w = len(grid), len(grid[0])
    def periodic_lines(axis):
        length = h if axis == 0 else w
        # line candidates are uniform-ish and recur with period >= 2
        counts = {}
        for i in range(length):
            line = grid[i] if axis == 0 else [grid[r][i] for r in range(h)]
            counts[i] = max(set(line), key=line.count)
        groups = {}
        for i, color in counts.items(): groups.setdefault(color, []).append(i)
        return max(groups.values(), key=len) if groups else []
    # Recurrent divider rows/columns define output lattice crossings.
    rs = periodic_lines(0)
    cs = periodic_lines(1)
    if len(rs) < 2 or len(cs) < 2:
        return [[grid[0][0]]]
    out=[]
    for r in rs[:-1]:
        row=[]
        for c in cs[:-1]:
            v=grid[r][c]
            if v == max(set(grid[r]), key=grid[r].count):
                # crossing is separator background: infer tile fill just below/right
                v=grid[min(r+1,h-1)][min(c+1,w-1)]
            row.append(v)
        out.append(row)
    return out
